{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈砚",
      "role": "protagonist",
      "identity": "青玄宗少宗主，剑道天才",
      "traits": ["清冷禁欲", "责任感极强", "嘴硬心软", "内心缺爱"],
      "overt_motivation": "维护青玄宗安危，带领宗门抵御魔界入侵，守护仙界和平",
      "covert_motivation": "摆脱宗族与宗门的规则束缚，不用再为别人的期待而活，追求自己真正想要的生活",
      "secret_fear": "害怕自己对谢无妄的感情暴露，连累宗门安危，也害怕谢无妄因为自己的身份受到伤害",
      "misperception_of_other": "以为谢无妄接近自己只是为了窃取青玄宗的秘境情报，对自己没有半分真心",
      "hidden_connection": "十岁时坠崖被年幼的谢无妄所救，失去了那段记忆，只留下一块残缺的玉佩作为信物"
    },
    {
      "name": "谢无妄",
      "role": "deuteragonist",
      "identity": "魔界少主，魔族未来的王",
      "traits": ["桀骜不驯", "外冷内热", "重情重义", "心思缜密"],
      "overt_motivation": "平定魔界内乱，带领魔族摆脱仙界千年的围剿打压，为魔族争得生存空间",
      "covert_motivation": "找到小时候救下的那个小道士（沈砚），和他安稳地生活在一起，不用再受阵营对立的折磨",
      "secret_fear": "害怕沈砚知道自己的魔族身份后厌恶自己，更害怕沈砚为了维护宗门亲手伤害自己",
      "misperception_of_other": "以为沈砚对自己只有正邪对立的敌意，哪怕偶尔流露的温柔也只是逢场作戏",
      "hidden_connection": "十岁时在魔界边境救了坠崖的小沈砚，一直收藏着对方掉落的半块玉佩，找了他整整一百年"
    }
  ],
  "supporting_characters": [
    {
      "name": "沈玄清",
      "function": "阻碍",
      "identity": "青玄宗宗主，沈砚的生父",
      "description": "古板固执，将宗门荣誉和仙界正邪之分刻进骨血，为了维护青玄宗的名声可以牺牲一切，包括自己儿子的幸福"
    },
    {
      "name": "夜枭",
      "function": "阻碍",
      "identity": "魔界大长老，谢无妄的叔父",
      "description": "野心勃勃，不满谢无妄对仙界的缓和政策，一直想夺权篡位，故意泄露谢无妄和沈砚的往来，挑起仙魔大战想坐收渔利"
    },
    {
      "name": "苏清鸢",
      "function": "助力",
      "identity": "青玄宗首席大弟子，沈砚的师姐",
      "description": "温柔通透，早就看出沈砚对谢无妄的心思，多次暗中帮两人打掩护，是沈砚唯一可以倾诉心事的人"
    },
    {
      "name": "阿左",
      "function": "助力",
      "identity": "谢无妄的贴身近卫",
      "description": "忠心耿耿，从谢无妄小时候就跟随他，知道他对沈砚的感情，多次帮两人传递消息，在谢无妄被夜枭陷害时挺身而出"
    }
  ],
  "relationship_dynamics": "沈砚与谢无妄初期在无妄秘境偶遇，互相隐瞒身份，在共同闯关的过程中互生好感，得知彼此真实身份后陷入阵营对立的痛苦拉扯；中期夜枭故意设计陷害，让两人产生小误会，以为对方背叛了自己，解开误会后两人感情升温，开始联手对抗来自宗门和魔界的双重压力；后期两人合力揭穿夜枭的阴谋，说服仙魔两界放下仇恨，打破持续千年的正邪对立规则，最终公开关系相守。"
}"}

